def is_image_file(filename: str) -> bool:
    if not isinstance(filename, str):
        filename = getattr(filename, "name", str(filename))
    return filename.lower().endswith((".jpg", ".jpeg", ".png", ".bmp", ".tiff", ".tif", ".webp"))


def is_pdf_file(filename: str) -> bool:
    if not isinstance(filename, str):
        filename = getattr(filename, "name", str(filename))
    return filename.lower().endswith(".pdf")


def load_image_from_bytes(uploaded_file) -> "Image.Image":
    """
    Loads an image into a PIL Image object with multiple fallback decoding strategies:
    1. Pillow (Image.open)
    2. OpenCV (cv2.imdecode)
    3. PyMuPDF (fitz)
    """
    data = None
    if isinstance(uploaded_file, (str, Path)):
        with open(str(uploaded_file), "rb") as f:
            data = f.read()
    elif hasattr(uploaded_file, "read"):
        if hasattr(uploaded_file, "seek"):
            uploaded_file.seek(0)
        data = uploaded_file.read()
    elif isinstance(uploaded_file, (bytes, bytearray)):
        data = bytes(uploaded_file)
    else:
        raise ValueError(f"Unsupported input type for image loading: {type(uploaded_file)}")

    if not data:
        raise ValueError("Provided image data is empty.")

    # Strategy 1: Standard PIL Image.open
    if Image is not None:
        try:
            img = Image.open(io.BytesIO(data))
            img.load()
            return img.convert("RGB")
        except Exception:
            pass

    # Strategy 2: OpenCV decoding fallback
    try:
        import cv2
        import numpy as np
        np_arr = np.frombuffer(data, np.uint8)
        img_mat = cv2.imdecode(np_arr, cv2.IMREAD_COLOR)
        if img_mat is not None:
            img_rgb = cv2.cvtColor(img_mat, cv2.COLOR_BGR2RGB)
            if Image is not None:
                return Image.fromarray(img_rgb)
    except Exception:
        pass

    # Strategy 3: PyMuPDF (fitz) pixmap decoding fallback
    if fitz is not None and Image is not None:
        try:
            doc = fitz.open(stream=data, filetype="image")
            page = doc[0]
            pix = page.get_pixmap(dpi=150)
            img_data = pix.tobytes("png")
            doc.close()
            img = Image.open(io.BytesIO(img_data))
            img.load()
            return img.convert("RGB")
        except Exception:
            pass

    raise RuntimeError("Failed to decode image data using PIL, OpenCV, or PyMuPDF.")


def _extract_with_winocr(image) -> str:
    """
    Extracts text using Windows 10/11 native OCR engine (Windows.Media.Ocr via winocr).
    Thread-safe and asyncio-safe (runs in isolated ThreadPoolExecutor to support Streamlit runtime).
    """
    if platform.system() != "Windows":
        return ""
    try:
        import winocr
        import concurrent.futures
        
        # Preprocessing: ensure within Windows OCR dimension limits (40 <= dim <= 2600)
        img = image.copy()
        max_dim = max(img.width, img.height)
        min_dim = min(img.width, img.height)
        
        if max_dim > 2400:
            scale = 2400.0 / max_dim
            new_size = (int(img.width * scale), int(img.height * scale))
            img = img.resize(new_size, Image.LANCZOS if hasattr(Image, "LANCZOS") else Image.Resampling.LANCZOS)
        elif min_dim < 60:
            scale = 120.0 / max(min_dim, 1)
            new_size = (int(img.width * scale), int(img.height * scale))
            img = img.resize(new_size, Image.BICUBIC if hasattr(Image, "BICUBIC") else Image.Resampling.BICUBIC)
        
        # Streamlit scripts run inside asyncio event loops; isolate sync call in a separate thread
        def _run_sync():
            return winocr.recognize_pil_sync(img)

        with concurrent.futures.ThreadPoolExecutor(max_workers=1) as executor:
            future = executor.submit(_run_sync)
            res = future.result(timeout=20)

        if isinstance(res, dict):
            # Prefer extracted lines for preserving formatting/line breaks
            lines = res.get("lines", [])
            if lines:
                text_lines = [line.get("text", "") for line in lines if isinstance(line, dict)]
                combined = "\n".join(filter(None, text_lines)).strip()
                if combined:
                    return combined
            text = res.get("text", "")
            if text:
                return text.strip()
    except Exception:
        pass
    return ""


def _find_tesseract_binary() -> str:
    """Finds tesseract.exe path on Windows or POSIX systems."""
    which_path = shutil.which("tesseract")
    if which_path:
        return which_path
    
    if platform.system() == "Windows":
        common_paths = [
            r"C:\Program Files\Tesseract-OCR\tesseract.exe",
            r"C:\Program Files (x86)\Tesseract-OCR\tesseract.exe",
            os.path.join(os.environ.get("LOCALAPPDATA", ""), r"Programs\Tesseract-OCR\tesseract.exe"),
            os.path.join(os.environ.get("LOCALAPPDATA", ""), r"Tesseract-OCR\tesseract.exe"),
            os.path.join(os.environ.get("USERPROFILE", ""), r"AppData\Local\Programs\Tesseract-OCR\tesseract.exe"),
            os.path.join(os.environ.get("USERPROFILE", ""), r"AppData\Local\Tesseract-OCR\tesseract.exe"),
        ]
        for path in common_paths:
            if path and os.path.exists(path):
                return path
    return ""


def _extract_with_tesseract(image) -> str:
    """Extracts text using pytesseract with automatic binary path discovery."""
    try:
        import pytesseract
    except ImportError:
        return ""

    tess_path = _find_tesseract_binary()
    if tess_path:
        pytesseract.pytesseract.tesseract_cmd = tess_path
        tessdata_dir = os.path.join(os.path.dirname(tess_path), "tessdata")
        if os.path.isdir(tessdata_dir) and "TESSDATA_PREFIX" not in os.environ:
            os.environ["TESSDATA_PREFIX"] = tessdata_dir

    try:
        text = pytesseract.image_to_string(image)
        return text.strip()
    except Exception:
        return ""


def _extract_with_easyocr(image) -> str:
    """Extracts text using easyocr as deep-learning fallback."""
    try:
        import easyocr
        import numpy as np
        reader = easyocr.Reader(["en"], gpu=False, verbose=False)
        img_np = np.array(image)
        results = reader.readtext(img_np, detail=0)
        return "\n".join(results).strip()
    except Exception:
        return ""


def extract_text_from_image(image) -> str:
    """
    Extracts text from a PIL Image using a multi-engine fallback strategy:
    1. Windows Native OCR (winocr) - Instant, zero setup on Windows
    2. Tesseract OCR (pytesseract) - Standard open-source OCR
    3. EasyOCR - Deep-learning based fallback
    """
    if image is None:
        return "[Error] Invalid image provided."

    # Engine 1: Windows Built-in OCR (Fastest and zero-dependency on Windows)
    text = _extract_with_winocr(image)
    if text:
        return text

    # Engine 2: Tesseract OCR (if installed/found)
    text = _extract_with_tesseract(image)
    if text:
        return text

    # Engine 3: EasyOCR (PyTorch-based fallback)
    text = _extract_with_easyocr(image)
    if text:
        return text

    return "[Warning] No text could be detected or extracted from the image. Please ensure the image is clear and contains readable text."


def extract_text_from_pdf(uploaded_file) -> str:
    if fitz is None:
        return "[Error] PyMuPDF (fitz) is not installed. PDF processing is unavailable."
    
    doc = None
    try:
        if isinstance(uploaded_file, (str, Path)):
            doc = fitz.open(str(uploaded_file))
        elif hasattr(uploaded_file, "read"):
            if hasattr(uploaded_file, "seek"):
                uploaded_file.seek(0)
            pdf_stream = io.BytesIO(uploaded_file.read())
            doc = fitz.open(stream=pdf_stream, filetype="pdf")
        else:
            return "[Error] Unsupported PDF input format."
        
        all_text = []
        is_scanned = True
        
        # First pass: try to extract direct digital text
        for page in doc:
            page_text = page.get_text().strip()
            if page_text:
                all_text.append(page_text)
                if len(page_text) > 50:
                    is_scanned = False
        
        extracted_text = "\n\n".join(all_text).strip()
        
        # If sufficient digital text found, return directly
        if extracted_text and not is_scanned:
            return extracted_text

        # Second pass (Scanned PDF): Perform OCR on rendered pages
        ocr_text_parts = []
        if Image is not None:
            for i in range(len(doc)):
                page = doc[i]
                pix = page.get_pixmap(dpi=300)
                img_data = pix.tobytes("png")
                img = Image.open(io.BytesIO(img_data)).convert("RGB")
                
                page_ocr = extract_text_from_image(img)
                if page_ocr and not page_ocr.startswith("[Error]") and not page_ocr.startswith("[Warning]"):
                    ocr_text_parts.append(page_ocr)
        
        final_ocr_text = "\n\n".join(ocr_text_parts).strip()
        
        if final_ocr_text and len(final_ocr_text) > len(extracted_text):
            return final_ocr_text
        if extracted_text:
            return extracted_text
            
        return "[Warning] No text could be extracted. The PDF might be blank or unreadable."
        
    except Exception as e:
        return f"[Error] Failed to extract text from PDF: {str(e)}"
    finally:
        if doc is not None:
            doc.close()


def extract_text_from_file(uploaded_file) -> str:
    """
    Extracts text from either an image or a PDF file.
    Supports both file paths (str/Path) and file-like objects (BytesIO / Streamlit UploadedFile).
    """
    filename = getattr(uploaded_file, "name", str(uploaded_file))
    
    if is_pdf_file(filename):
        return extract_text_from_pdf(uploaded_file)
    
    try:
        image = load_image_from_bytes(uploaded_file)
        return extract_text_from_image(image)
    except Exception as e:
        return f"[Error] Failed to load image: {str(e)}"



