def _fig_to_pdf_image(fig, width=400, height=300):
    """Converts a plotly figure to a reportlab Image."""
    from reportlab.platypus import Image as RLImage
    import tempfile
    import os
    if fig is None:
        return None
    try:
        # Save to temp file
        fd, path = tempfile.mkstemp(suffix=".png")
        os.close(fd)
        fig.write_image(path, format="png", engine="kaleido", width=800, height=600)
        img = RLImage(path, width=width, height=height)
        return img
    except Exception as e:
        print(f"Error generating chart image: {e}")
        return None

def _get_benchmark_chart(tool_key, leaderboard):
    """Creates a plotly chart for model benchmarking."""
    import pandas as pd
    import plotly.express as px
    if not leaderboard or not isinstance(leaderboard, list):
        return None
    valid_records = [c for c in leaderboard if isinstance(c, dict) and c.get("valid", False)]
    if not valid_records:
        valid_records = [c for c in leaderboard if isinstance(c, dict)]
    if not valid_records:
        return None
    df_board = pd.DataFrame(valid_records)
    tool_key = tool_key.lower()
    try:
        if "trend" in tool_key and "rmse" in df_board.columns:
            plot_df = df_board[df_board["rmse"].fillna(999999) < 90000].copy()
            if plot_df.empty: plot_df = df_board.copy()
            fig = px.bar(plot_df, x="model", y="rmse", color="is_winner" if "is_winner" in plot_df.columns else None, title="Trend Model RMSE (Lower is Better)", text=plot_df["rmse"].round(2))
        elif "cohort" in tool_key and "silhouette" in df_board.columns:
            fig = px.bar(df_board, x="model", y="silhouette", color="is_winner" if "is_winner" in df_board.columns else None, title="Clustering Silhouette Score (Higher is Better)", text=df_board["silhouette"].round(2))
        elif "risk" in tool_key and "roc_auc" in df_board.columns:
            fig = px.bar(df_board, x="model", y="roc_auc", color="is_winner" if "is_winner" in df_board.columns else None, title="Risk Model ROC-AUC (Higher is Better)", text=df_board["roc_auc"].round(2))
        elif "anomaly" in tool_key and "separation_score" in df_board.columns:
            fig = px.bar(df_board, x="model", y="separation_score", color="is_winner" if "is_winner" in df_board.columns else None, title="Anomaly Separation Score (Higher is Better)", text=df_board["separation_score"].round(2))
        else:
            return None
        
        fig.update_layout(showlegend=False, margin=dict(l=20, r=20, t=40, b=20))
        return fig
    except Exception as e:
        print(f"Error creating chart: {e}")
        return None

def generate_pdf_report(df, col_map, results, llm_insights=None, dynamic_summary=None, mapping_details=None):
    """Generate comprehensive 9-section PDF report."""
    import io
    from datetime import datetime
    from reportlab.lib.pagesizes import A4
    from reportlab.lib import colors
    from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
    from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak
    from reportlab.lib.units import inch

    buffer = io.BytesIO()
    doc = SimpleDocTemplate(buffer, pagesize=A4, rightMargin=50, leftMargin=50, topMargin=50, bottomMargin=50)
    
    styles = getSampleStyleSheet()
    title_style = ParagraphStyle('CustomTitle', parent=styles['Heading1'], fontSize=24, spaceAfter=20, alignment=1, textColor=colors.darkblue)
    heading_style = ParagraphStyle('CustomHeading', parent=styles['Heading2'], fontSize=16, spaceAfter=10, textColor=colors.darkblue)
    sub_heading = ParagraphStyle('SubHeading', parent=styles['Heading3'], fontSize=12, spaceAfter=8, textColor=colors.dimgrey)
    normal_style = styles['Normal']
    
    content = []
    
    # Title Page
    content.append(Paragraph("Prescription Trend AI: Clinical Intelligence Report", title_style))
    content.append(Paragraph(f"Generated on: {datetime.now().strftime('%B %d, %Y at %I:%M %p')}", normal_style))
    content.append(Spacer(1, 30))
    
    # 1. Summary & Data
    content.append(Paragraph("1. Summary & Data", heading_style))
    if dynamic_summary:
        content.append(Paragraph(dynamic_summary, normal_style))
    else:
        content.append(Paragraph(f"Dataset encompasses {len(df):,} records across {len(df.columns)} dimensions.", normal_style))
    content.append(Spacer(1, 10))
    
    # 2. Canonical Schema & Evidence
    content.append(Paragraph("2. Canonical Schema & Evidence", heading_style))
    if mapping_details:
        map_data = [["Dataset Column", "Canonical Concept", "Confidence", "Evidence"]]
        for col, d in mapping_details.items():
            map_data.append([
                col[:20], 
                d.get("canonical", "OTHER"), 
                f"{int(d.get('confidence', 0)*100)}%", 
                d.get("evidence", "")[:40] + "..."
            ])
        t = Table(map_data, colWidths=[1.5*inch, 1.2*inch, 0.8*inch, 3.0*inch])
        t.setStyle(TableStyle([('BACKGROUND', (0,0), (-1,0), colors.HexColor('#2E4088')), ('TEXTCOLOR', (0,0), (-1,0), colors.whitesmoke), ('ALIGN', (0,0), (-1,-1), 'LEFT'), ('GRID', (0,0), (-1,-1), 1, colors.grey)]))
        content.append(t)
    else:
        content.append(Paragraph("Mapping details not available.", normal_style))
    content.append(Spacer(1, 20))
    
    # 3. Dynamic Model Selection
    content.append(Paragraph("3. Dynamic Model Selection", heading_style))
    content.append(Paragraph("Model competition results for each executed analytical tool.", normal_style))
    content.append(Spacer(1, 10))
    
    has_charts = False
    if results:
        for tool_name, result in results.items():
            if result.get("status") == "ok" and "leaderboard" in result:
                fig = _get_benchmark_chart(tool_name, result["leaderboard"])
                if fig:
                    img = _fig_to_pdf_image(fig, width=400, height=250)
                    if img:
                        content.append(Paragraph(f"{tool_name.replace('_tool', '').title()} Model Performance", sub_heading))
                        content.append(img)
                        content.append(Spacer(1, 15))
                        has_charts = True
    if not has_charts:
        content.append(Paragraph("No dynamic model competition charts available.", normal_style))
    content.append(PageBreak())
    
    # 4. Risk Stratification
    content.append(Paragraph("4. Risk Stratification", heading_style))
    risk_res = results.get("risk_tool", {}) if results else {}
    if risk_res.get("status") == "ok":
        content.append(Paragraph("Risk tool executed successfully. Significant risk patterns identified.", normal_style))
        # Add a table of feature importances if they exist
        findings = risk_res.get("findings", [])
        for finding in findings:
            content.append(Paragraph(f"• {finding}", normal_style))
    else:
        content.append(Paragraph("Risk analysis not performed or insufficient data.", normal_style))
    content.append(Spacer(1, 20))
    
    # 5. Cohort Phenotypes
    content.append(Paragraph("5. Cohort Phenotypes", heading_style))
    cohort_res = results.get("cohort_tool", {}) if results else {}
    if cohort_res.get("status") == "ok":
        for finding in cohort_res.get("findings", []):
            content.append(Paragraph(f"• {finding}", normal_style))
    else:
        content.append(Paragraph("Cohort analysis not performed.", normal_style))
    content.append(Spacer(1, 20))
    
    # 6. Anomaly Detection
    content.append(Paragraph("6. Anomaly Detection", heading_style))
    anomaly_res = results.get("anomaly_tool", {}) if results else {}
    if anomaly_res.get("status") == "ok":
        for finding in anomaly_res.get("findings", []):
            content.append(Paragraph(f"• {finding}", normal_style))
    else:
        content.append(Paragraph("Anomaly analysis not performed.", normal_style))
    content.append(Spacer(1, 20))
    
    # 7. Co-Prescriptions
    content.append(Paragraph("7. Co-Prescriptions", heading_style))
    pattern_res = results.get("pattern_tool", {}) if results else {}
    if pattern_res.get("status") == "ok":
        for finding in pattern_res.get("findings", []):
            content.append(Paragraph(f"• {finding}", normal_style))
    else:
        content.append(Paragraph("Co-prescription pattern mining not performed.", normal_style))
    content.append(Spacer(1, 20))
    
    # 8. Temporal Trends
    content.append(Paragraph("8. Temporal Trends", heading_style))
    trend_res = results.get("trend_tool", {}) if results else {}
    if trend_res.get("status") == "ok":
        for finding in trend_res.get("findings", []):
            content.append(Paragraph(f"• {finding}", normal_style))
    else:
        content.append(Paragraph("Temporal trend forecasting not performed.", normal_style))
    content.append(PageBreak())
    
    # 9. AI Executive Synthesis
    content.append(Paragraph("9. AI Executive Synthesis", heading_style))
    if llm_insights and "ERROR_OLLAMA_DOWN" not in llm_insights:
        insights_style = ParagraphStyle('Insights', parent=styles['Normal'], backColor=colors.HexColor('#F8F9FA'), borderColor=colors.HexColor('#E0E0E0'), borderWidth=1, borderPadding=10, fontSize=10, leading=14)
        # Parse newlines correctly
        for para in llm_insights.split('\n'):
            if para.strip():
                content.append(Paragraph(para.strip(), insights_style))
                content.append(Spacer(1, 5))
    else:
        content.append(Paragraph("AI synthesis unavailable (Ollama server may be down).", normal_style))
        
    doc.build(content)
    return buffer.getvalue()
